// Converts protocol-v4.json and test-vectors/v4-{frames,acks,risk}.json into C headers for the host tests.
// Usage: node tools/gen_vectors.mjs   (writes test/vectors.h and test/json_constants.h; the generated files are committed)
import { readFileSync, writeFileSync } from 'node:fs';
const root = new URL('../../', import.meta.url);
const J = (p) => JSON.parse(readFileSync(new URL(p, root), 'utf8'));
const spec = J('protocol-v4.json'), frames = J('test-vectors/v4-frames.json'), acks = J('test-vectors/v4-acks.json'), risk = J('test-vectors/v4-risk.json');

const cstr = (s) => '"' + Array.from(new TextEncoder().encode(s)).map((b) => (b >= 0x20 && b < 0x7f && b !== 0x22 && b !== 0x5c && b !== 0x3f ? String.fromCharCode(b) : '\\' + b.toString(8).padStart(3, '0'))).join('') + '"';
const nibs = (symbols) => symbols.flat().map((n) => n.toString(16)).join('');
const ch = spec.channelIds;
const bytes = (a) => '{' + a.join(',') + '}';

let c = '/* Generated by tools/gen_vectors.mjs from protocol-v4.json. Do not edit by hand. */\n#ifndef JSON_CONSTANTS_H\n#define JSON_CONSTANTS_H\n';
const def = (k, v) => { c += `#define J_${k} ${v}\n`; };
def('VERSION', spec.version); def('SPACING_MHZ', Math.round(spec.spacingHz * 1000)); def('TONES', spec.tonesPerGroup);
def('RAMP_MS', Math.round(spec.rampSeconds * 1000)); def('GAP_MS', Math.round(spec.gapSeconds * 1000)); def('HOP_MS', Math.round(spec.hopSeconds * 1000));
def('THRESHOLD_PERMILLE', Math.round(spec.preambleThreshold * 1000)); def('HEADER_BYTES', spec.headerBytes);
def('MAGIC_PAYLOAD', spec.magicPayload); def('MAGIC_ACK', spec.magicAck); def('MAGIC_REFERENCE', spec.magicReference); def('MAGIC_RISK', spec.magicRisk);
def('REF_BYTES', spec.referenceBytes); def('REF_DATA', spec.referenceDataBytes); def('REF_PARITY', spec.referenceParity); def('MOTHER_PARITY', spec.motherParity);
def('BLOCK_DATA', spec.blockData); def('BLOCK_PARITY', spec.blockParity); def('BLOCK_HEADER', spec.blockHeader); def('MAX_BLOCKS', spec.maxBlocks);
def('RISK_LENGTH', spec.riskLength); def('RISK_PARITY', spec.riskParity); def('RISK_MAX_HOPS', spec.riskMaxHops); def('ACK_LENGTH', spec.ackLength); def('ACK_PARITY', spec.ackParity);
c += `static const unsigned char J_PREAMBLE[8][4] = {${spec.preamble.map(bytes).join(',')}};\n`;
const names = Object.keys(ch);
c += `/* by channel id: bin, groups, amp in thousandths, symbol_us, window_start_us */\nstatic const unsigned J_BANDS[${names.length}][5] = {\n`;
for (const n of names) { const b = spec.bands[n]; c += `  {${b.bin},${b.groups},${Math.round(b.toneAmplitude * 1000)},${Math.round(b.symbolSeconds * 1e6)},${Math.round(b.windowStartSeconds * 1e6)}}, /* ${n} = ${ch[n]} */\n`; }
c += '};\n';
c += `static const unsigned char J_KEY_NORMAL[${names.length}][2] = {${names.map((n) => bytes(spec.preambleKeys.normal[n])).join(',')}};\n`;
const rob = names.filter((n) => spec.preambleKeys.robust[n]);
c += `static const unsigned char J_KEY_ROBUST[${rob.length}][2] = {${rob.map((n) => bytes(spec.preambleKeys.robust[n])).join(',')}}; /* ${rob.join(',')} */\n`;
c += '#endif\n';
writeFileSync(new URL('../test/json_constants.h', import.meta.url), c);

let v = '/* Generated by tools/gen_vectors.mjs from test-vectors/v4-{frames,acks,risk}.json. Do not edit by hand. */\n#ifndef VECTORS_H\n#define VECTORS_H\n';
v += 'typedef struct { const char *name, *text; int payload, band, set, robust; const char *header, *body, *syms; } vec_frame_t;\n';
v += 'static const vec_frame_t V_FRAMES[] = {\n';
for (const x of frames.vectors) v += ` {${cstr(x.name)},${cstr(x.text)},${x.mode === 'payload' ? 1 : 0},${ch[x.band]},${x.set},${x.profile === 'robust' ? 1 : 0},"${x.header}","${x.body}","${nibs(x.symbols)}"},\n`;
v += '};\n';
v += 'typedef struct { int band, receipt; const char *header, *body, *syms; } vec_ack_t;\nstatic const vec_ack_t V_ACKS[] = {\n';
for (const x of acks.vectors) v += ` {${ch[x.band]},${x.receipt ? 1 : 0},"${x.header}","${x.body}","${nibs(x.symbols)}"},\n`;
v += '};\n';
v += 'typedef struct { int band, reason, source, hops; unsigned char own[3], intruder[3]; const char *header, *body, *syms; } vec_risk_t;\nstatic const vec_risk_t V_RISKS[] = {\n';
for (const x of risk.vectors) v += ` {${ch[x.band]},${x.reason},${x.source},${x.hops},${bytes(x.own)},${bytes(x.intruder)},"${x.header}","${x.body}","${nibs(x.symbols)}"},\n`;
v += '};\n#define V_NFRAMES (sizeof V_FRAMES / sizeof V_FRAMES[0])\n#define V_NACKS (sizeof V_ACKS / sizeof V_ACKS[0])\n#define V_NRISKS (sizeof V_RISKS / sizeof V_RISKS[0])\n#endif\n';
writeFileSync(new URL('../test/vectors.h', import.meta.url), v);
console.log(`${frames.vectors.length} frames, ${acks.vectors.length} acks, ${risk.vectors.length} risks`);
